# Типовая конфигурация:
upstream app {
    server app1:8080;
    server app2:8080;
    # round-robin по умолчанию
}
server {
    listen 443 ssl;
    ssl_certificate /etc/ssl/app.crt;
    location /static/ {
        root /var/www;      # статика сам
    }
    location / {
        proxy_pass http://app;   # прокси
