class User {
    private long id;
    private String email;

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;                 // идентичность
        if (!(o instanceof User u)) return false;   // тип + null
        return id == u.id && Objects.equals(email, u.email);
    }

    @Override
    public int hashCode() {
        return Objects.hash(id, email); // те же поля, что в equals
    }
}

