class A {
    static int COUNT = 0;   // область: класс, жизнь: JVM
    int field;              // область: объект

    void m(int param) {     // область: метод
        int local = 1;      // отсюда до конца блока
        if (local > 0) {
            int inner = 2;  // только в if
        }
        // inner недоступна здесь
        int field = 9;      // shadowing! this.field — поле
