function Todo({ item, onToggle }) {   // props — вход
  return (
    <li onClick={() => onToggle(item.id)}>
      {item.done ? '✅' : '⬜'} {item.text}
    </li>
  )
}

function TodoList() {
  const [todos, setTodos] = useState([])      // state

  const toggle = (id) =>
    setTodos(todos.map(t =>                  // иммутабельное
      t.id === id ? {...t, done: !t.done} : t // обновление
    ))

  return <ul>{todos.map(t =>
    <Todo key={t.id} item={t} onToggle={toggle} />)}</ul>
}

function Search() {
  const [q, setQ] = useState('')
  const [res, setRes] = useState([])

  useEffect(() => {
    if (!q) return setRes([])
    const c = new AbortController()
    fetch('/api?q='+q, {signal: c.signal})
      .then(r => r.json()).then(setRes)
    return () => c.abort()
  }, [q])

  return <>
    <input value={q} onChange={e => setQ(e.target.value)} />
    <List items={res} />
  </>
}

