// Stateless:
// каждый запрос с Authorization —
// сервер не помнит «сессии» клиента

// Структура:
// eyJhbGciOiJIUzI1NiJ9           header
// .eyJzdWIiOiJ1MSIsImV4cCI6MTcwMH0 payload
// .SflKxwRJS...                  signature

// Payload:
// {"sub":"user-5","role":"admin",
//  "exp":1715000000,"iss":"auth-svc"}

