class Positive:
    # Data-дескриптор: поле с валидацией
    def __set_name__(self, owner, name):
        self.name = name           # имя атрибута (3.6+)

    def __get__(self, obj, objtype=None):
        if obj is None:
            return self            # доступ через класс
        return obj.__dict__[self.name]

    def __set__(self, obj, value):
        if value < 0:
            raise ValueError(f"{self.name} must be >= 0")
        obj.__dict__[self.name] = value

class Product:
    price = Positive()   # дескриптор как атрибут класса
    count = Positive()

p = Product()
p.price = 100    # ок — через __set__ с валидацией
p.price = -5     # ValueError
p.price          # 100 — через __get__

