# Ручной итератор — класс
class Squares:
    def __init__(self, n):
        self.i, self.n = 0, n
    def __iter__(self): return self
    def __next__(self):
        if self.i >= self.n: raise StopIteration
        self.i += 1
        return self.i ** 2

# Тот же итератор — генератором, в разы короче
def squares(n):
    for i in range(n):
        yield (i + 1) ** 2

