func quicksort(a []int) {
    if len(a) < 2 { return }
    pivot := a[len(a)-1]
    i := 0
    for j := 0; j < len(a)-1; j++ {
        if a[j] < pivot {
            a[i], a[j] = a[j], a[i]
            i++
        }
    }
    a[i], a[len(a)-1] = a[len(a)-1], a[i]
    quicksort(a[:i])      // левая часть
    quicksort(a[i+1:])    // правая часть
}

