type Counter struct {
    mu sync.Mutex
    n  int
}
func (c *Counter) Inc() {
    c.mu.Lock()
    defer c.mu.Unlock()   // гарантия!
    c.n++
}
func (c *Counter) Val() int {
    c.mu.Lock()
    defer c.mu.Unlock()
    return c.n
}

// RWMutex для read-heavy:
type Cache struct {
    mu sync.RWMutex
    m  map[string]V
}
func (c *Cache) Get(k string) V {
    c.mu.RLock(); defer c.mu.RUnlock()
    return c.m[k]     // читатели параллельно
}

class Counter {
    private int n;
    private final Object lock = new Object();

    void inc() {
        synchronized (lock) { n++; } // атомарно
    }
    synchronized void dec() { n--; } // монитор = this
}

