# 1) Итератор-класс — больше контроля, больше кода
class Batched:
    def __init__(self, it, n):
        self.it, self.n = iter(it), n
    def __iter__(self): return self
    def __next__(self):
        batch = []
        for _ in range(self.n):
            try: batch.append(next(self.it))
            except StopIteration:
                break
        if not batch: raise StopIteration
        return batch

# 2) Генератор — то же самое короче
def batched(it, n):
    batch = []
    for x in it:
        batch.append(x)
        if len(batch) == n:
            yield batch; batch = []
    if batch: yield batch

list(batched(range(7), 3))  # [[0,1,2],[3,4,5],[6]]

