from abc import ABC, abstractmethod

class Shape(ABC):
    @abstractmethod
    def area(self) -> float: ...

    @abstractmethod
    def perimeter(self) -> float: ...

    # конкретный метод — общая реализация
    def describe(self):
        return f"area={self.area()}, p={self.perimeter()}"

s = Shape()        # TypeError: can't instantiate abstract class

class Circle(Shape):
    def __init__(self, r): self.r = r
    def area(self): return 3.14 * self.r ** 2
    def perimeter(self): return 2 * 3.14 * self.r

class Bad(Shape):
    def area(self): return 0
Bad()   # TypeError — perimeter не реализован

# isinstance/issubclass работают
isinstance(Circle(1), Shape)   # True

