class Resource : IDisposable {
    private IntPtr _handle;      // unmanaged
    private Stream _stream;      // managed
    private bool _disposed;

    public void Dispose() {
        Dispose(true);
        GC.SuppressFinalize(this); // финализ.
    }                              // не нужен

    protected virtual void Dispose(bool disposing) {
        if (_disposed) return;
        if (disposing) {
            _stream?.Dispose();   // managed
        }
        CloseHandle(_handle);     // unmanaged —
        //                         // в обоих путях
        _disposed = true;
    }
    ~Resource() => Dispose(false);
}

