class Sum extends RecursiveTask<Long> {
    protected Long compute() {
        if (end - start < 10_000) return sumSeq();
        int mid = (start+end)/2;
        var l = new Sum(start, mid); l.fork();   // async
        var r = new Sum(mid, end);
        return r.compute() + l.join();           // join
    }
}
